  `fee_per_contract` decimal(10,4) DEFAULT NULL,
  `maint_margin` bigint DEFAULT NULL,
  `trade_start` time DEFAULT NULL,
  `trade_end` time DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
