CREATE TABLE `order_audit_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `time` datetime DEFAULT NULL,
  `event_type` varchar(50) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
