  `symbol` varchar(20) DEFAULT NULL,
  `order_price` decimal(15,4) DEFAULT NULL,
  `side` varchar(10) DEFAULT NULL,
  `qty` int DEFAULT NULL,
  `fee` double DEFAULT NULL,
  `pnl` double DEFAULT NULL,
  `leverage` double DEFAULT NULL,
  `margin` double DEFAULT NULL,
  `position_snapshot` text,
  `open_order_snapshot` text,
  `filled_price` decimal(15,4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_audit_user_time` (`user_id`,`time`)
) ENGINE=InnoDB AUTO_INCREMENT=10595 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
