DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `symbol` varchar(20) NOT NULL,
  `side` enum('BUY','SELL') NOT NULL,
  `order_type` enum('MARKET','LIMIT','MIT','STOP') NOT NULL,
  `order_price` decimal(15,4) NOT NULL,
  `filled_price` decimal(15,4) DEFAULT NULL,
  `trigger_price` decimal(15,4) DEFAULT NULL,
  `position_price` decimal(15,4) DEFAULT NULL,
  `qty` int NOT NULL,
  `status` enum('PENDING','FILLED','CANCELED') DEFAULT 'PENDING',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_tp_sl` tinyint(1) DEFAULT '0',
  `tp_sl_type` varchar(20) DEFAULT NULL,
  `stop_type` varchar(10) DEFAULT NULL,
  `tick_count` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4857 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
